/** Stop and remove the currently playing emoji overlay, if any. */
void emoji_idle_stop(void);

/**
 * Voice-state override for the fullscreen overlay (Doubao listen/speak).
 *
 * Only retargets the animation; never opens or closes the overlay:
 *  - overlay showing  -> switch to the named emoji immediately and loop it;
 *  - overlay hidden   -> remembered, applied when the overlay is next created.
 * Pass NULL to clear the override and resume the automatic idle rotation.
 * Idempotent: repeating the same name does not restart the keyframes.
 */
void emoji_idle_set_voice_emoji(const char *name);

