lv_obj_t *emoji_idle_play(lv_obj_t *parent, const char *name,
                          emoji_idle_exit_cb_t on_exit)
{
    int idx = emoji_index_from_name(name);
    if (idx < 0) return NULL;

    emoji_idle_stop();
    g_next_emoji = idx;
    g_named_play = true;

    return emoji_idle_create(parent, on_exit);
}

