void emoji_idle_set_voice_emoji(const char *name)
{
    int idx = name ? emoji_index_from_name(name) : -1;
    if (idx == g_voice_emoji) return;  /* no change: keep keyframes running */
    g_voice_emoji = idx;

    if (!g_idle.overlay) return;       /* hidden: create() applies it later */

    if (idx >= 0) {
        g_idle.emoji_idx = idx;
        g_idle.keyframe  = 0;
        show_keyframe();               /* switch without waiting 300 ms */
    }
    /* idx < 0: leave the current emoji; anim_cb resumes auto-rotation
     * at the next keyframe wrap. */
}

